using System.Linq;
using Autodesk.Revit.DB;
using Autodesk.Revit.DB.Plumbing;

var doc = Document;
// setup: a piping system type, a pipe type, and the lowest level
var systemType = new FilteredElementCollector(doc).OfClass(typeof(PipingSystemType)).Cast<PipingSystemType>().First();
var pipeType   = new FilteredElementCollector(doc).OfClass(typeof(PipeType)).Cast<PipeType>().First();
var level      = new FilteredElementCollector(doc).OfClass(typeof(Level)).Cast<Level>().OrderBy(l => l.Elevation).First();
var start = new XYZ(0, 5, 9);
var end   = new XYZ(20, 5, 9);

ElementId pipeId = null;
// step 1: create the pipe from two points inside the connector's transaction
Connector.WithTransaction(doc, () => {
    var pipe = Pipe.Create(doc, systemType.Id, pipeType.Id, level.Id, start, end);
    pipeId = pipe.Id;
});

var created = (Pipe)doc.GetElement(pipeId);
var length  = created.get_Parameter(BuiltInParameter.CURVE_ELEM_LENGTH)?.AsDouble();
return new { pipeId = pipeId.ToString(), pipeType = pipeType.Name, systemType = systemType.Name, level = level.Name, lengthFeet = length };
